#!/usr/bin/env python3
import json,re,glob,os,math,csv,collections
from pathlib import Path

ROOT=Path('/mnt/data/hagalaz_sieve')
SEEDS=[
 'laplace','laplace-beltrami','laplace beltrami','operator','solenoid','solenoidal',
 'silence','silent','quiet','consciousness','hagalaz','universal indicatrix','indicatrix',
 'whirligig','gendarme','graticule','graticulum','ontic','wacky','alberr','holojesu',
 'activator','transcender','superhelix','superhelical','hyperhelix','hyperhelical',
 'torus','toroid','toroidal','sphere','spheres','rotation','scale','origin','holonomy',
 'closure','frame transport','contact','jamming','jam','nesting','nested','projection',
 'theta_4','theta4','θ4','delta c','δc','Δc','delta rotation','Δrotation','delta scale','Δscale'
]
STOP=set('''the a an and or but if then else as at by for from in into of on onto out over under to up with without within is are was were be been being have has had do does did not no yes this that these those it its they them their you your i me my we our us he she his her who whom what which when where why how can could may might must shall should would will just very more most much many some any all each every other another same own about around through during before after between than so too also only even still now here there because while though although yet per via vs versus both either neither such'.split())
STOP.update(['chatgpt','said','nathan','mcknight','user','assistant','tool','file','files','turn','message','content','source','document','text'])
WORD_RE=re.compile(r"(?u)\b[A-Za-zΑ-Ωα-ωθΔδ][A-Za-z0-9_Α-Ωα-ωθΔδ'’\-]{2,}\b")
DOTRUN_RE=re.compile(r'\.{3,}|…+')
PUNCT_ONLY_RE=re.compile(r'^\s*[.…。·•⋅]+\s*$')

def msg_text(msg):
    parts=((msg.get('content') or {}).get('parts') or [])
    out=[]
    for x in parts:
        if isinstance(x,str): out.append(x)
        elif isinstance(x,dict):
            # preserve visible textual fragments only
            for k in ('text','caption','title'):
                if isinstance(x.get(k),str): out.append(x[k])
    return '\n'.join(out)

def load_json_conversation(path):
    o=json.load(open(path,encoding='utf-8'))
    mapping=o.get('mapping') or {}
    current=o.get('current_node')
    active=set()
    n=current
    while n and n in mapping and n not in active:
        active.add(n); n=mapping[n].get('parent')
    rows=[]
    for nid,node in mapping.items():
        msg=node.get('message') or {}
        text=msg_text(msg)
        if not text.strip(): continue
        author=(msg.get('author') or {})
        rows.append({
            'file':path.name,'title':o.get('title'),'node_id':nid,'parent':node.get('parent'),
            'active_branch':nid in active,'role':author.get('role') or '', 'name':author.get('name') or '',
            'create_time':msg.get('create_time') or 0,'text':text
        })
    rows.sort(key=lambda r:(r['create_time'] or 0,r['node_id']))
    for i,r in enumerate(rows): r['ordinal']=i
    return rows

def load_txt(path):
    txt=path.read_text(encoding='utf-8',errors='replace')
    # preserve coarse paragraphs as units; don't pretend these are chat turns
    blocks=[b.strip() for b in re.split(r'\n\s*\n',txt) if b.strip()]
    return [{'file':path.name,'title':path.stem,'node_id':f'block:{i}','parent':'','active_branch':True,
             'role':'document','name':'','create_time':0,'text':b,'ordinal':i} for i,b in enumerate(blocks)]

rows=[]
for p in ROOT.iterdir():
    if p.suffix.lower()=='.json':
        try: rows.extend(load_json_conversation(p))
        except Exception as e: print('WARN',p,e)
    elif p.suffix.lower()=='.txt': rows.extend(load_txt(p))

# document frequencies over lexical tokens
units=[]
df=collections.Counter()
for r in rows:
    toks=[w.lower().strip("-'’") for w in WORD_RE.findall(r['text'])]
    toks=[w for w in toks if len(w)>=3 and w not in STOP and not w.isdigit()]
    r['_tokens']=toks
    s=set(toks)
    df.update(s); units.append(r)
N=max(len(units),1)

def seed_hits(text):
    lo=text.lower().replace('–','-').replace('—','-')
    got=[]
    for s in SEEDS:
        if s.lower() in lo: got.append(s)
    return got

def distinctive_terms(r,top=30):
    c=collections.Counter(r['_tokens']); vals=[]
    for w,n in c.items():
        idf=math.log((N+1)/(df[w]+1))+1
        score=(1+math.log(n))*idf
        vals.append((score,w,n,df[w]))
    vals.sort(reverse=True)
    return vals[:top]

# seed hits and punctuation morphology
hits=[]; punct=[]
byfile=collections.defaultdict(list)
for r in rows: byfile[r['file']].append(r)
for r in rows:
    h=seed_hits(r['text'])
    dotchars=r['text'].count('.')+r['text'].count('…')
    runs=DOTRUN_RE.findall(r['text'])
    punct_only=bool(PUNCT_ONLY_RE.fullmatch(r['text']))
    # acute hyperellipsisosis heuristic: >=4 runs OR >=12 dot chars OR >=8% dots, with length guard
    density=dotchars/max(len(r['text']),1)
    acute=(len(runs)>=4 or dotchars>=12 or (len(r['text'])<=240 and density>=.08 and dotchars>=5))
    if h:
        hits.append((r,h,distinctive_terms(r)))
    if punct_only or acute:
        punct.append((r,punct_only,acute,dotchars,len(runs),density))

# seed cooccurrence and nearby-turn neighbor candidate scores
seed_pair=collections.Counter(); candidate=collections.Counter(); examples=collections.defaultdict(list)
for r,h,dt in hits:
    for a in h:
        for b in h:
            if a<b: seed_pair[(a,b)]+=1
    for score,w,n,d in dt:
        # prioritize rare/distinctive, but retain everything above trivial threshold
        candidate[w]+=score*len(set(h))
        if len(examples[w])<5:
            examples[w].append((r['file'],r['role'],r['node_id'],h,r['text'][:280].replace('\n',' ')))
    # +/- 2 messages in same file
    seq=byfile[r['file']]; idx=r['ordinal']
    for j in range(max(0,idx-2),min(len(seq),idx+3)):
        if j==idx: continue
        nr=seq[j]
        for score,w,n,d in distinctive_terms(nr,15):
            candidate[w]+=0.35*score*len(set(h))
            if len(examples[w])<5:
                examples[w].append((nr['file'],nr['role'],nr['node_id'],['NEAR:'+','.join(h)],nr['text'][:280].replace('\n',' ')))

# write hit csv
with open(ROOT/'seed_hits.csv','w',encoding='utf-8',newline='') as f:
    w=csv.writer(f); w.writerow(['file','role','active_branch','node_id','seeds','text'])
    for r,h,dt in hits:
        w.writerow([r['file'],r['role'],r['active_branch'],r['node_id'],' | '.join(h),r['text']])
with open(ROOT/'punctuation_turns.csv','w',encoding='utf-8',newline='') as f:
    w=csv.writer(f); w.writerow(['file','role','active_branch','node_id','punct_only','acute','dotchars','dotruns','density','text'])
    for r,po,ac,dc,dr,de in punct:
        w.writerow([r['file'],r['role'],r['active_branch'],r['node_id'],po,ac,dc,dr,de,r['text']])

# report
report=[]
report.append(f'UNITS\t{len(rows)}')
report.append(f'SEED_HIT_UNITS\t{len(hits)}')
report.append(f'PUNCT_OR_HYPERELLIPSIS_UNITS\t{len(punct)}')
report.append('\nSEED_COUNTS')
sc=collections.Counter(s for _,hs,_ in hits for s in hs)
for s,n in sc.most_common(): report.append(f'{n:5d}\t{s}')
report.append('\nPUNCTUATION_COUNTS_BY_FILE_ROLE')
pc=collections.Counter((r['file'],r['role'],'punct_only' if po else 'acute') for r,po,ac,*_ in punct)
for k,n in pc.most_common(): report.append(f'{n:5d}\t{k}')
report.append('\nTOP_SEED_PAIRS')
for (a,b),n in seed_pair.most_common(100): report.append(f'{n:5d}\t{a} <> {b}')
report.append('\nTOP_DISTINCTIVE_BRANCH_TERMS')
for w,score in candidate.most_common(250):
    ex=' || '.join(f'{x[0]}:{x[1]}:{x[2][:8]}:{"/".join(x[3])}: {x[4]}' for x in examples[w][:2])
    report.append(f'{score:9.2f}\t{w}\tDF={df[w]}\t{ex}')
(ROOT/'branch_sieve_report.txt').write_text('\n'.join(report),encoding='utf-8')
print('\n'.join(report[:160]))
PY
